      xs: "gap-2",
      sm: "gap-3 sm:gap-4",
      md: "gap-4 sm:gap-6 lg:gap-8",
      lg: "gap-6 sm:gap-8 lg:gap-10",
      xl: "gap-8 sm:gap-12 lg:gap-16",
    },
    align: {
      start: "items-start",
      center: "items-center",
      end: "items-end",
      stretch: "items-stretch",
    },
  },
  defaultVariants: {
    cols: 1,
    layout: "default",
    gap: "md",
    align: "stretch",
  },
});

export interface GridProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof gridVariants> {
  /**
   * The underlying HTML element tag to render when not animated.
   * @default "div"
   */
  as?: React.ElementType;
  /**
   * Enables Google Stitch staggered waterfall entrance animation.
   * @default false
   */
  animate?: boolean;
  /**
   * Delay between each child element in seconds.
   * @default 0.06
   */
  staggerDelay?: number;
}

const Grid = React.forwardRef<HTMLDivElement, GridProps>(
  (
    {
      as: Component = "div",
      cols,
      layout = "default",
      gap = "md",
      align = "stretch",
      animate = false,
      staggerDelay = 0.06,
      className,
      children,
      ...props
    },
    ref
  ) => {
    // If an asymmetric layout is provided, ignore uniform cols
    const resolvedCols = layout !== "default" ? undefined : (cols ?? 1);

    const gridClassName = cn(
      gridVariants({
        cols: resolvedCols,
        layout,
        gap,
        align,
      }),
      className
    );

    if (animate) {
      const containerVariants: Variants = {
        hidden: { opacity: 0 },
        visible: {
          opacity: 1,
          transition: {
            staggerChildren: staggerDelay,
            delayChildren: 0.05,
          },
        },
      };

      return (
        <motion.div
          ref={ref}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-40px" }}
          variants={containerVariants}
          className={gridClassName}
          {...(props as HTMLMotionProps<"div">)}
        >
          {children}
        </motion.div>
      );
    }

    return React.createElement(Component, { ref, className: gridClassName, ...props }, children);
  }
);

Grid.displayName = "Grid";

export { Grid, gridVariants };

