"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type InputVariant = "flat" | "bordered" | "underlined";
export type InputSize = "sm" | "md" | "lg";
export type InputRadius = "none" | "md" | "lg" | "full";
export type InputLabelPlacement = "outside" | "inside";

const inputWrapperVariants = cva(
  "group relative flex items-center w-full transition-all duration-150 text-foreground outline-none select-none",
  {
    variants: {
      variant: {
        flat: "bg-zinc-100/90 hover:bg-zinc-200/70 focus-within:bg-white dark:bg-[#202124] dark:hover:bg-[#26272b] dark:focus-within:bg-[#161618] border border-black/5 dark:border-white/10 focus-within:border-indigo-500/60 dark:focus-within:border-indigo-400/60 focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-400/20 shadow-2xs",
        bordered:
          "bg-transparent border border-zinc-200 dark:border-white/10 hover:border-zinc-300 dark:hover:border-white/20 focus-within:border-indigo-500/60 dark:focus-within:border-indigo-400/60 focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-400/20 shadow-2xs",
        underlined:
          "bg-transparent rounded-none border-0 border-b-2 border-zinc-200 dark:border-white/10 hover:border-zinc-400 dark:hover:border-white/25 focus-within:border-indigo-500 dark:focus-within:border-indigo-400 px-0.5",
      },
      size: {
        sm: "min-h-9 text-xs px-3.5 gap-2",
        md: "min-h-11 text-sm px-4 gap-2.5",
        lg: "min-h-13 text-base px-5 gap-3",
      },
      radius: {
        none: "rounded-none",
        md: "rounded-xl",
        lg: "rounded-2xl",
        full: "rounded-full",
      },
      isInvalid: {
        true: "!border-rose-500 focus-within:!border-rose-500 focus-within:!ring-rose-500/20",
        false: "",
      },
      isDisabled: {
        true: "opacity-50 pointer-events-none select-none cursor-not-allowed",
        false: "",
      },
      labelPlacement: {
        outside: "",
        inside: "items-stretch",
      },
    },
    compoundVariants: [
      {
        variant: "underlined",
        className: "rounded-none",
      },
      {
        labelPlacement: "inside",
        size: "sm",
        className: "min-h-12 py-1.5 px-3.5",
      },
      {
        labelPlacement: "inside",
        size: "md",
        className: "min-h-14 py-2 px-4",
      },
      {
        labelPlacement: "inside",
        size: "lg",
        className: "min-h-16 py-2.5 px-5",
      },
      {
        radius: "full",
        size: "sm",
        className: "px-4.5",
      },
      {
        radius: "full",
        size: "md",
        className: "px-5.5",
      },
      {
        radius: "full",
        size: "lg",
        className: "px-6.5",
      },
    ],
    defaultVariants: {
      variant: "flat",
      size: "md",
      radius: "md",
      isInvalid: false,
      isDisabled: false,
      labelPlacement: "outside",
    },
  }
);

export interface InputProps
  extends
    Omit<React.InputHTMLAttributes<HTMLInputElement>, "size">,
    VariantProps<typeof inputWrapperVariants> {
  variant?: InputVariant;
  size?: InputSize;
  /** Backward-compatibility alias for size */
  inputSize?: InputSize;
  radius?: InputRadius;
  label?: React.ReactNode;
  labelPlacement?: InputLabelPlacement;
  isInvalid?: boolean;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  startContent?: React.ReactNode;
  endContent?: React.ReactNode;
  isClearable?: boolean;
  onClear?: () => void;
  /** Optional custom class name applied directly to the inner input wrapper div */
  wrapperClassName?: string;
}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      wrapperClassName,
      variant = "flat",
      size = "md",
      inputSize,
      radius = "md",
      label,
      labelPlacement = "outside",
      isInvalid = false,
      disabled = false,
      isDisabled: propIsDisabled,
      description,
      errorMessage,
      startContent,
      endContent,
      isClearable = false,
      onClear,
      value,
      defaultValue,
      onChange,
      type = "text",
      id: providedId,
      ...props
    },
    ref
  ) => {
    const generatedId = React.useId();
    const inputId = providedId ?? generatedId;
    const resolvedDisabled = disabled || Boolean(propIsDisabled);
    // Support inputSize alias for seamless backwards-compatibility
    const resolvedSize = inputSize ?? size ?? "md";

    const innerInputRef = React.useRef<HTMLInputElement | null>(null);

    // Merge internal and external refs
    React.useImperativeHandle(ref, () => innerInputRef.current as HTMLInputElement);

    const [uncontrolledVal, setUncontrolledVal] = React.useState<string>(() => {
      if (defaultValue !== undefined) return String(defaultValue);
      return "";
    });

    const isControlled = value !== undefined;
    const currentVal = isControlled ? String(value ?? "") : uncontrolledVal;
    const hasValue = Boolean(currentVal && currentVal.length > 0);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) {
        setUncontrolledVal(e.target.value);
      }
      onChange?.(e);
    };

    const handleClearClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      e.preventDefault();
      e.stopPropagation();

      if (!isControlled) {
        setUncontrolledVal("");
      }

      if (innerInputRef.current) {
        innerInputRef.current.value = "";
        // Dispatch synthetic change event to trigger reactive form subscribers
        const event = new Event("input", { bubbles: true });
        innerInputRef.current.dispatchEvent(event);
      }

      onClear?.();
      innerInputRef.current?.focus();
    };

    const isInsideLabel = labelPlacement === "inside" && Boolean(label);

    return (
      <div className={cn("flex w-full flex-col text-left", className)}>
        {/* Outside Label */}
        {label && labelPlacement === "outside" && (
          <label
            htmlFor={inputId}
            className={cn(
              "mb-1.5 text-xs font-semibold tracking-tight text-zinc-800 transition-colors select-none dark:text-zinc-200",
              isInvalid ? "text-rose-600 dark:text-rose-400" : "text-foreground",
              resolvedDisabled && "cursor-not-allowed opacity-50"
            )}
          >
            {label}
          </label>
        )}

        {/* Input Interactive Box Container */}
        <div
          data-slot="input-wrapper"
          className={cn(
            inputWrapperVariants({
              variant,
              size: resolvedSize,
              radius,
              isInvalid,
              isDisabled: resolvedDisabled,
              labelPlacement,
            }),
            wrapperClassName
          )}
          onClick={() => innerInputRef.current?.focus()}
        >
          {/* Start Content Slot */}
          {startContent && (
            <div className="text-muted-foreground flex shrink-0 items-center justify-center select-none">
              {startContent}
            </div>
          )}

          {/* Main Input Element or Inside Label Wrapper */}
          {isInsideLabel ? (
            <div className="flex h-full min-w-0 flex-1 flex-col justify-center py-0.5">
              <label
                htmlFor={inputId}
                className={cn(
                  "text-[10px] leading-tight font-semibold tracking-wide uppercase transition-colors select-none",
                  isInvalid ? "text-rose-600" : "text-muted-foreground"
                )}
              >
                {label}
              </label>
              <input
                id={inputId}
                ref={innerInputRef}
                type={type}
                value={isControlled ? value : uncontrolledVal}
                onChange={handleInputChange}
                disabled={resolvedDisabled}
                aria-invalid={isInvalid ? "true" : undefined}
                className="text-foreground placeholder:text-muted-foreground w-full border-none bg-transparent p-0 leading-tight font-normal text-inherit outline-none disabled:cursor-not-allowed"
                {...props}
              />
            </div>
          ) : (
            <input
              id={inputId}
              ref={innerInputRef}
              type={type}
              value={isControlled ? value : uncontrolledVal}
              onChange={handleInputChange}
              disabled={resolvedDisabled}
              aria-invalid={isInvalid ? "true" : undefined}
              className="text-foreground placeholder:text-muted-foreground h-full w-full border-none bg-transparent font-normal text-inherit outline-none disabled:cursor-not-allowed"
              {...props}
            />
          )}

          {/* Interactive Clear Button */}
          {isClearable && hasValue && !resolvedDisabled && (
            <button
              type="button"
              aria-label="Clear input value"
              tabIndex={-1}
              onClick={handleClearClick}
              className="shrink-0 cursor-pointer rounded-lg p-1 text-zinc-400 transition-all hover:bg-black/5 hover:text-zinc-700 active:scale-90 dark:text-zinc-500 dark:hover:bg-white/10 dark:hover:text-zinc-200"
            >
              <svg
                className="h-3.5 w-3.5"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <line x1="18" y1="6" x2="6" y2="18" />
                <line x1="6" y1="6" x2="18" y2="18" />
              </svg>
            </button>
          )}

          {/* End Content Slot */}
          {endContent && (
            <div className="text-muted-foreground flex shrink-0 items-center justify-center select-none">
              {endContent}
            </div>
          )}
        </div>

        {/* Validation Error Message or Helper Description */}
        {isInvalid && errorMessage ? (
          <p
            role="alert"
            className="animate-in fade-in-0 slide-in-from-top-0.5 mt-1.5 flex items-center gap-1 text-xs font-medium text-rose-600 duration-150"
          >
            {errorMessage}
          </p>
        ) : description ? (
          <p className="text-muted-foreground mt-1.5 text-xs">{description}</p>
        ) : null}
      </div>
    );
  }
);

Input.displayName = "Input";

export { Input, inputWrapperVariants };

// packages/core/src/components/InputOTP/InputOTP.tsx
"use client";

import * as React from "react";
import { Dot } from "lucide-react";
import { cn } from "../utils/cn";

export type InputOTPSize = "sm" | "md" | "lg";
export type InputOTPRadius = "none" | "sm" | "md" | "lg" | "full";

const groupRadiusStyles: Record<InputOTPRadius, string> = {
  none: "rounded-none",
  sm: "rounded-md",
  md: "rounded-xl",
  lg: "rounded-2xl",
  full: "rounded-full",
};

interface InputOTPContextValue {
  value: string;
  focusedIndex: number;
  isFocused: boolean;
  maxLength: number;
  disabled: boolean;
  size: InputOTPSize;
  radius: InputOTPRadius;
  isInvalid: boolean;
}

const InputOTPContext = React.createContext<InputOTPContextValue>({
  value: "",
  focusedIndex: -1,
  isFocused: false,
  maxLength: 6,
  disabled: false,
  size: "md",
  radius: "md",
  isInvalid: false,
});

export const useInputOTPContext = () => React.useContext(InputOTPContext);

// ----------------------------------------------------
// InputOTP Root
// ----------------------------------------------------

export interface InputOTPProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  /**
   * Controlled string value
   */
  value?: string;
  /**
   * Uncontrolled initial string value
   */
  defaultValue?: string;
  /**
   * Callback fired when value changes
   */
  onChange?: (value: string) => void;
  /**
   * Callback fired when all slots are filled
   */
  onComplete?: (value: string) => void;
  /**
   * Number of OTP code slots (default 6)
   */
  maxLength?: number;
  /**
   * Disables user input
   */
  disabled?: boolean;
  /**
   * Automatically focuses input on mount
   */
  autoFocus?: boolean;
  /**
   * Sizing of slot tiles
   */
  size?: InputOTPSize;
  /**
   * Border radius applied to the slot group container
   */
  radius?: InputOTPRadius;
  /**
   * Whether the input is in an invalid error state
   */
  isInvalid?: boolean;
  /**
   * Allowed input regex pattern (default: digits only)
   */
  pattern?: RegExp;
}

export const InputOTP = React.forwardRef<HTMLDivElement, InputOTPProps>(
  (
    {
      className,
      value: controlledValue,
      defaultValue = "",
      onChange,
      onComplete,
      maxLength = 6,
      disabled = false,
      autoFocus = false,
      size = "md",
      radius = "md",
      isInvalid = false,
      pattern = /^\d+$/,
      children,
      ...props
    },
    ref
  ) => {
    const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue);
    const value = controlledValue !== undefined ? controlledValue : uncontrolledValue;

    const [isFocused, setIsFocused] = React.useState(false);
    const inputRef = React.useRef<HTMLInputElement | null>(null);

    const focusedIndex = Math.min(value.length, maxLength - 1);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const raw = e.target.value;
      const filtered = pattern
        ? raw
            .split("")
            .filter((c) => pattern.test(c))
            .join("")
        : raw;
      const nextVal = filtered.slice(0, maxLength);

      if (controlledValue === undefined) {
        setUncontrolledValue(nextVal);
      }
      onChange?.(nextVal);

      if (nextVal.length === maxLength) {
        onComplete?.(nextVal);
      }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
        // Allow native arrow navigation inside input
      }
    };

    return (
      <InputOTPContext.Provider
        value={{
          value,
          focusedIndex: isFocused ? focusedIndex : -1,
          isFocused,
          maxLength,
          disabled,
          size,
          radius,
          isInvalid,
        }}
      >
        <div
          ref={ref}
          onClick={() => {
            if (!disabled && inputRef.current) {
              inputRef.current.focus();
            }
          }}
          className={cn(
            "relative inline-flex cursor-text items-center gap-2.5 select-none",
            disabled && "cursor-not-allowed opacity-50",
            className
          )}
          {...props}
        >
          {/* Accessible hidden HTML Input receiving touch and key events */}
          <input
            ref={inputRef}
            type="text"
            inputMode="numeric"
            autoComplete="one-time-code"
            autoFocus={autoFocus}
            disabled={disabled}
            value={value}
            maxLength={maxLength}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            aria-label={props["aria-label"] || "One-Time Password code"}
            aria-invalid={isInvalid}
            className="pointer-events-none absolute inset-0 h-full w-full opacity-0"
          />

          {children}
        </div>
      </InputOTPContext.Provider>
    );
  }
);

InputOTP.displayName = "InputOTP";

// ----------------------------------------------------
// InputOTP Group
// ----------------------------------------------------

export interface InputOTPGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  radius?: InputOTPRadius;
}

export const InputOTPGroup = React.forwardRef<HTMLDivElement, InputOTPGroupProps>(
  ({ className, radius: propRadius, ...props }, ref) => {
    const context = useInputOTPContext();
    const effectiveRadius = propRadius ?? context?.radius ?? "md";

    return (
      <div
        ref={ref}
        className={cn(
          "flex items-center divide-x divide-black/[0.08] overflow-hidden border border-black/[0.08] bg-white shadow-xs transition-all duration-150 dark:divide-white/[0.08] dark:border-white/[0.08] dark:bg-[#161618]",
          groupRadiusStyles[effectiveRadius],
          className
        )}
        {...props}
      />
    );
  }
);

InputOTPGroup.displayName = "InputOTPGroup";

// ----------------------------------------------------
// InputOTP Slot
// ----------------------------------------------------

export interface InputOTPSlotProps extends React.HTMLAttributes<HTMLDivElement> {
  index: number;
}

const slotSizeStyles: Record<InputOTPSize, string> = {
  sm: "w-9 h-10 text-sm",
  md: "w-11 h-12 text-base",
  lg: "w-13 h-14 text-lg",
};

export const InputOTPSlot = React.forwardRef<HTMLDivElement, InputOTPSlotProps>(
  ({ index, className, ...props }, ref) => {
    const { value, focusedIndex, isFocused, disabled, size, isInvalid } = useInputOTPContext();

    const char = value[index] || "";
    const isActive = isFocused && (index === focusedIndex || (index === value.length && index < 6));

    return (
      <div
        ref={ref}
        role="presentation"
        className={cn(
          "text-foreground relative flex items-center justify-center font-semibold transition-all duration-150",
          slotSizeStyles[size],
          isActive && "ring-ring ring-offset-background z-10 ring-2",
          isInvalid && "ring-offset-background ring-2 ring-rose-600",
          disabled && "bg-muted/40",
          className
        )}
        {...props}
      >
        {char}

        {/* Blinking cursor when slot is empty and active */}
        {isActive && !char && (
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
            <div className="animate-caret-blink bg-foreground h-4 w-px duration-1000" />
          </div>
        )}
      </div>
    );
  }
);

InputOTPSlot.displayName = "InputOTPSlot";

// ----------------------------------------------------
// InputOTP Separator
// ----------------------------------------------------

export interface InputOTPSeparatorProps extends React.HTMLAttributes<HTMLDivElement> {}

export const InputOTPSeparator = React.forwardRef<HTMLDivElement, InputOTPSeparatorProps>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        role="separator"
        aria-hidden="true"
        className={cn("text-muted-foreground flex items-center", className)}
        {...props}
      >
        <Dot className="h-5 w-5" />
      </div>
    );
  }
);

InputOTPSeparator.displayName = "InputOTPSeparator";

