"use client";
import * as React from "react";
import {
  AnimatePresence,
  motion,
  useReducedMotion,
  useScroll,
  type HTMLMotionProps,
  type Variants,
} from "framer-motion";
import { Button } from "../Button";
import { cn } from "../utils/cn";

export const quietEase = [0.22, 1, 0.36, 1] as const;

export interface MotionRevealProps extends HTMLMotionProps<"div"> {
  distance?: number;
  once?: boolean;
}

export const MotionReveal = React.forwardRef<HTMLDivElement, MotionRevealProps>(
  ({ children, distance = 18, once = true, className, ...props }, ref) => {
    const reduce = useReducedMotion();
    const canObserve = typeof IntersectionObserver !== "undefined";
    const active = !reduce && canObserve;
    return (
      <motion.div
        ref={ref}
        initial={active ? { opacity: 0.01, y: distance } : false}
        whileInView={active ? { opacity: 1, y: 0 } : undefined}
        viewport={{ once, amount: 0.12 }}
        transition={{ duration: 0.3, ease: quietEase }}
        className={className}
        {...props}
      >
        {children}
      </motion.div>
    );
  }
);
MotionReveal.displayName = "MotionReveal";

const staggerVariants: Variants = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.07, delayChildren: 0.03 } },
};
const itemVariants: Variants = {
  hidden: { opacity: 0, y: 12 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.45, ease: quietEase } },
};

export const MotionStagger = React.forwardRef<HTMLDivElement, HTMLMotionProps<"div">>(
  ({ children, ...props }, ref) => {
    const reduce = useReducedMotion();
    const active = !reduce && typeof IntersectionObserver !== "undefined";
    return (
      <motion.div
        ref={ref}
        initial={active ? "hidden" : false}
        whileInView={active ? "visible" : undefined}
        viewport={{ once: true, amount: 0.12 }}
        variants={staggerVariants}
        {...props}
      >
        {children}
      </motion.div>
    );
  }
);
MotionStagger.displayName = "MotionStagger";

export const MotionStaggerItem = React.forwardRef<HTMLDivElement, HTMLMotionProps<"div">>(
  (props, ref) => <motion.div ref={ref} variants={itemVariants} {...props} />
);
MotionStaggerItem.displayName = "MotionStaggerItem";

export interface MotionCrossfadeProps extends React.HTMLAttributes<HTMLDivElement> {
  transitionKey: React.Key;
}

export const MotionCrossfade = React.forwardRef<HTMLDivElement, MotionCrossfadeProps>(
  ({ transitionKey, children, className, ...props }, ref) => {
    const reduce = useReducedMotion();
    return (
      <div ref={ref} className={cn("relative", className)} {...props}>
        <AnimatePresence initial={false} mode="wait">
          <motion.div
            key={transitionKey}
            initial={reduce ? false : { opacity: 0.01, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reduce ? undefined : { opacity: 0 }}
            transition={{ duration: 0.24, ease: quietEase }}
          >
            {children}
          </motion.div>
        </AnimatePresence>
      </div>
    );
  }
);
MotionCrossfade.displayName = "MotionCrossfade";

export interface MotionTickerProps extends React.HTMLAttributes<HTMLDivElement> {
  items: React.ReactNode[];
  duration?: number;
  paused?: boolean;
}

export const MotionTicker = React.forwardRef<HTMLDivElement, MotionTickerProps>(
  ({ items, duration = 24, paused = false, className, ...props }, ref) => {
    const reduce = useReducedMotion();
    const [interacting, setInteracting] = React.useState(false);
    const running = !reduce && !paused && !interacting;
    return (
      <div
        ref={ref}
        className={cn("relative overflow-hidden", className)}
        onMouseEnter={() => setInteracting(true)}
        onMouseLeave={() => setInteracting(false)}
        onFocusCapture={() => setInteracting(true)}
        onBlurCapture={() => setInteracting(false)}
        {...props}
      >
        <motion.div
          className="flex w-max items-center"
          animate={running ? { transform: ["translateX(0%)", "translateX(-50%)"] } : undefined}
          transition={{ duration, ease: "linear", repeat: Infinity }}
        >
          <div className="flex shrink-0 items-center">{items}</div>
          <div className="flex shrink-0 items-center" aria-hidden="true">
            {items}
          </div>
        </motion.div>
      </div>
    );
  }
);
MotionTicker.displayName = "MotionTicker";

export interface MotionSlideshowProps extends React.HTMLAttributes<HTMLDivElement> {
  slides: React.ReactNode[];
  label?: string;
}

export const MotionSlideshow = React.forwardRef<HTMLDivElement, MotionSlideshowProps>(
  ({ slides, label = "Slideshow", className, ...props }, ref) => {
    const reduce = useReducedMotion();
    const [active, setActive] = React.useState(0);
    if (!slides.length) return null;
    const select = (next: number) => setActive((next + slides.length) % slides.length);
    return (
      <div ref={ref} className={cn("space-y-4", className)} aria-label={label} {...props}>
        <div className="relative overflow-hidden" aria-live="polite">
          <AnimatePresence initial={false} mode="wait">
            <motion.div
              key={active}
              initial={reduce ? false : { opacity: 0, x: 12 }}
              animate={{ opacity: 1, x: 0 }}
              exit={reduce ? undefined : { opacity: 0, x: -12 }}
              transition={{ duration: 0.32, ease: quietEase }}
            >
              {slides[active]}
            </motion.div>
          </AnimatePresence>
        </div>
        <div className="flex items-center justify-between gap-3">
          <Button variant="outline" size="sm" onClick={() => select(active - 1)}>
            Previous
          </Button>
          <span
            className="text-sm tabular-nums"
            aria-label={`Slide ${active + 1} of ${slides.length}`}
          >
            {active + 1} / {slides.length}
          </span>
          <Button variant="outline" size="sm" onClick={() => select(active + 1)}>
            Next
          </Button>
        </div>
      </div>
    );
  }
);
MotionSlideshow.displayName = "MotionSlideshow";

export function MotionScrollProgress({ className }: { className?: string }) {
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll();
  return (
    <motion.div
      aria-hidden="true"
      className={cn("bg-primary fixed inset-x-0 top-0 z-50 h-0.5 origin-left", className)}
      style={{ scaleX: reduce ? 0 : scrollYProgress }}
    />
  );
}

// packages/core/src/components/Navbar/Navbar.tsx
"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { cva, type VariantProps } from "class-variance-authority";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";
import { cn } from "../utils/cn";

export type NavbarLayout = "standard" | "admin";
export type NavbarPosition = "static" | "sticky" | "fixed";
export type NavbarMaxWidth = "sm" | "md" | "lg" | "xl" | "2xl" | "full";
export type NavbarLogoPosition = "left" | "center" | "right";
export type NavbarStyleVariant = "glassmorphism" | "transparent" | "floating-full";
export type NavbarMobileMenuVariant = "top" | "left" | "right" | "fullscreen";

interface NavbarContextValue {
  isMenuOpen: boolean;
  setIsMenuOpen: (isOpen: boolean | ((prev: boolean) => boolean)) => void;
  layout: NavbarLayout;
  logoPosition: NavbarLogoPosition;
  styleVariant: NavbarStyleVariant;
  mobileMenuVariant: NavbarMobileMenuVariant;
  isContained: boolean;
  isBordered: boolean;
  isBlurred: boolean;
}

const NavbarContext = React.createContext<NavbarContextValue | undefined>(undefined);

export function useNavbarContext() {
  const context = React.useContext(NavbarContext);
  if (!context) {
    throw new Error("Navbar sub-components must be rendered within a <Navbar> provider.");
  }
  return context;
}

const navbarVariants = cva("w-full transition-all duration-200 box-border", {
  variants: {
    position: {
      static: "relative z-40",
      sticky: "sticky top-0 z-40",
      fixed: "fixed top-0 left-0 right-0 z-40",
    },
    styleVariant: {
      glassmorphism:
        "bg-white/80 dark:bg-[#161618]/85 backdrop-blur-2xl backdrop-saturate-150 border-b border-black/[0.06] dark:border-white/[0.08]",
      transparent: "bg-transparent border-b border-transparent shadow-none",
      "floating-full":
        "mt-2 sm:mt-4 mx-auto max-w-5xl rounded-full border border-black/[0.08] dark:border-white/[0.1] bg-white/90 dark:bg-[#161618]/90 backdrop-blur-2xl shadow-lg shadow-black/5 dark:shadow-black/40 px-3 sm:px-6 transition-all",
    },
    isBordered: {
      true: "",
      false: "border-transparent dark:border-transparent",
    },
    isBlurred: {
      true: "",
      false: "backdrop-blur-none bg-white dark:bg-[#161618]",
    },
  },
  defaultVariants: {
    position: "sticky",
    styleVariant: "glassmorphism",
    isBordered: true,
    isBlurred: true,
  },
});

const containerMaxWidths: Record<NavbarMaxWidth, string> = {
  sm: "max-w-screen-sm",
  md: "max-w-screen-md",
  lg: "max-w-screen-lg",
  xl: "max-w-screen-xl",
  "2xl": "max-w-screen-2xl",
  full: "max-w-full",
};

export interface NavbarProps
  extends React.HTMLAttributes<HTMLElement>, VariantProps<typeof navbarVariants> {
  layout?: NavbarLayout;
  logoPosition?: NavbarLogoPosition;
  styleVariant?: NavbarStyleVariant;
  mobileMenuVariant?: NavbarMobileMenuVariant;
  position?: NavbarPosition;
  isBordered?: boolean;
  isBlurred?: boolean;
  maxWidth?: NavbarMaxWidth;
  isMenuOpen?: boolean;
  onMenuOpenChange?: (isOpen: boolean) => void;
  isMenuDefaultOpen?: boolean;
  isContained?: boolean;
  lockScroll?: boolean;
}

const Navbar = React.forwardRef<HTMLElement, NavbarProps>(
  (
    {
      className,
      layout = "standard",
      logoPosition = "left",
      styleVariant = "glassmorphism",
      mobileMenuVariant = "top",
      position = "sticky",
      isBordered = true,
      isBlurred = true,
      maxWidth = "full",
      isMenuOpen: controlledIsMenuOpen,
      onMenuOpenChange,
      isMenuDefaultOpen = false,
      isContained = false,
      lockScroll = true,
      children,
      ...props
    },
    ref
  ) => {
    const internalRef = React.useRef<HTMLElement>(null);
    const mergedRef = React.useMemo(() => {
      if (typeof ref === "function") {
        return (node: HTMLElement | null) => {
          ref(node);
          internalRef.current = node;
        };
      } else if (ref) {
        return (node: HTMLElement | null) => {
          (ref as React.MutableRefObject<HTMLElement | null>).current = node;
          internalRef.current = node;
        };
      }
      return internalRef;
    }, [ref]);

    const [uncontrolledIsMenuOpen, setUncontrolledIsMenuOpen] =
      React.useState<boolean>(isMenuDefaultOpen);

    const isControlled = controlledIsMenuOpen !== undefined;
    const isMenuOpen = isControlled ? controlledIsMenuOpen : uncontrolledIsMenuOpen;

    const setIsMenuOpen = React.useCallback(
      (value: boolean | ((prev: boolean) => boolean)) => {
        const nextValue = typeof value === "function" ? value(isMenuOpen) : value;
        if (!isControlled) {
          setUncontrolledIsMenuOpen(nextValue);
        }
        onMenuOpenChange?.(nextValue);
      },
      [isControlled, isMenuOpen, onMenuOpenChange]
    );

    // Prevent body-scroll leak when mobile drawer is open in full viewport mode
    React.useEffect(() => {
      // Find the correct document context in case we are rendered in an iframe portal
      const currentDocument =
        (typeof window !== "undefined" && internalRef.current?.ownerDocument) ||
        (typeof document !== "undefined" ? document : null);

      if (isMenuOpen && lockScroll && !isContained && currentDocument) {
        const docBody = currentDocument.body;
        const originalOverflow = docBody.style.overflow;
        const originalPaddingRight = docBody.style.paddingRight;
        const currentWindow = currentDocument.defaultView || window;
        const scrollbarWidth = currentWindow
          ? currentWindow.innerWidth - currentDocument.documentElement.clientWidth
          : 0;

        docBody.style.overflow = "hidden";
        if (scrollbarWidth > 0) {
          docBody.style.paddingRight = `${scrollbarWidth}px`;
        }

        return () => {
          docBody.style.overflow = originalOverflow;
          docBody.style.paddingRight = originalPaddingRight;
        };
      }
    }, [isMenuOpen, lockScroll, isContained, internalRef.current]);

    const contextValue = React.useMemo(
      () => ({
        isMenuOpen,
        setIsMenuOpen,
        layout,
        logoPosition,
        styleVariant,
        mobileMenuVariant,
        isContained,
        isBordered,
        isBlurred,
      }),
      [
        isMenuOpen,
        setIsMenuOpen,
        layout,
        logoPosition,
        styleVariant,
        mobileMenuVariant,
        isContained,
        isBordered,
        isBlurred,
      ]
    );

    const isFloating = styleVariant === "floating-full";

    // Separate NavbarMenu from main header children so drawer overlays are never constrained by the h-16 flex row
    const barChildren: React.ReactNode[] = [];
    const leftRightFullscreenMenuChildren: React.ReactNode[] = [];
    const topMenuChildren: React.ReactNode[] = [];

    React.Children.forEach(children, (child) => {
      if (
        React.isValidElement(child) &&
        ((child.type as any)?.displayName === "NavbarMenu" ||
          (child.type as any)?.__isNavbarMenu ||
          child.type === NavbarMenu ||
          (child.props as any)?.variant !== undefined ||
          (child.props as any)?.isContained !== undefined)
      ) {
        if ((child.props as any)?.variant === "top" || !(child.props as any)?.variant) {
          topMenuChildren.push(child);
        } else {
          leftRightFullscreenMenuChildren.push(child);
        }
      } else {
        barChildren.push(child);
      }
    });

    return (
      <NavbarContext.Provider value={contextValue}>
        <nav
          ref={mergedRef}
          data-logo-position={logoPosition}
          data-style-variant={styleVariant}
          data-mobile-variant={mobileMenuVariant}
          className={cn(
            navbarVariants({
              position,
              styleVariant,
              isBordered,
              isBlurred,
              className,
            }),
            isMenuOpen && "z-50",
            isMenuOpen &&
              styleVariant === "transparent" &&
              "bg-white transition-colors dark:bg-[#161618]",
            isContained && styleVariant !== "floating-full" && "rounded-t-2xl",
            isContained && !isMenuOpen && styleVariant !== "floating-full" && "rounded-b-2xl"
          )}
          {...props}
        >
          <div
            className={cn(
              "mx-auto flex h-16 w-full flex-nowrap items-center justify-between px-4 sm:px-6",
              !isFloating && containerMaxWidths[maxWidth],
              isFloating && "px-3 sm:px-5"
            )}
          >
            {barChildren}
          </div>
          {topMenuChildren}
        </nav>
        {leftRightFullscreenMenuChildren}
      </NavbarContext.Provider>
    );
  }
);
Navbar.displayName = "Navbar";

/* -------------------------------------------------------------------------------------------------
 * NavbarBrand
 * -----------------------------------------------------------------------------------------------*/

export interface NavbarBrandProps extends React.HTMLAttributes<HTMLDivElement> {
  position?: NavbarLogoPosition;
}

const NavbarBrand = React.forwardRef<HTMLDivElement, NavbarBrandProps>(
  ({ className, position: explicitPosition, children, ...props }, ref) => {
    const { logoPosition: contextPosition } = useNavbarContext();
    const logoPosition = explicitPosition || contextPosition;

    const logoPositionClasses: Record<NavbarLogoPosition, string> = {
      left: "justify-start mr-auto shrink-0",
      center: "justify-center mx-auto shrink-0",
      right: "justify-end ml-auto order-last shrink-0",
    };

    return (
      <div
        ref={ref}
        data-position={logoPosition}
        className={cn(
          "flex shrink-0 cursor-pointer items-center gap-2.5 font-bold tracking-tight whitespace-nowrap text-zinc-900 select-none dark:text-zinc-50",
          logoPositionClasses[logoPosition],
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
NavbarBrand.displayName = "NavbarBrand";

/* -------------------------------------------------------------------------------------------------
 * NavbarContent (Mobile-First Responsive Container: Center/Links hide on mobile, show on md:)
 * -----------------------------------------------------------------------------------------------*/

export type NavbarContentJustify = "start" | "center" | "end";

export interface NavbarContentProps extends React.HTMLAttributes<HTMLUListElement> {
  justify?: NavbarContentJustify;
  wrap?: boolean;
  hideOnMobile?: boolean;
}

const NavbarContent = React.forwardRef<HTMLUListElement, NavbarContentProps>(
  ({ className, justify = "start", wrap = false, hideOnMobile, children, ...props }, ref) => {
    const justifyClasses: Record<NavbarContentJustify, string> = {
      start: "justify-start mr-auto shrink-0",
      center: "justify-center flex-1 min-w-0 px-2",
      end: "justify-end ml-auto shrink-0",
    };

    // Center navigation links container strictly hides on mobile (hidden md:flex) by default unless className provides display rules
    const hasCustomDisplay =
      className && /(^|\s)(hidden|flex|inline-flex|block)(\s|$)/.test(className);
    const shouldHideOnMobile =
      hideOnMobile !== undefined ? hideOnMobile : !hasCustomDisplay && justify === "center";

    return (
      <ul
        ref={ref}
        className={cn(
          "m-0 min-w-0 shrink-0 list-none items-center gap-2 p-0 sm:gap-4 lg:gap-5",
          wrap ? "flex-wrap" : "flex-nowrap",
          shouldHideOnMobile ? "hidden md:flex" : "flex",
          justifyClasses[justify],
          className
        )}
        {...props}
      >
        {children}
      </ul>
    );
  }
);
NavbarContent.displayName = "NavbarContent";

