"use client";
import * as React from "react";
import {
  Radar,
  RadarChart as RechartsRadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  ResponsiveContainer,
  Tooltip,
  Legend,
} from "recharts";
import { cn } from "../utils/cn";
import { ChartTooltip } from "../ChartTooltip";
import { motion } from "framer-motion";

export interface RadarChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  data: any[];
  index: string;
  categories: string[];
  colors?: string[];
  valueFormatter?: (value: number) => string;
  showGridLines?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  gridType?: "polygon" | "circle";
  showRadiusAxis?: boolean;
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  fillOpacity?: number;
  children?: React.ReactNode;
}

const defaultColors = [
  "var(--color-primary-500, #4F46E5)",
  "var(--color-cyan-500, #06B6D4)",
  "var(--color-success-500, #10B981)",
  "var(--color-warning-500, #F59E0B)",
  "var(--color-danger-500, #F43F5E)",
  "var(--color-secondary-500, #8B5CF6)",
];

const RadarChart = React.forwardRef<HTMLDivElement, RadarChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showGridLines = true,
      showLegend = true,
      showTooltip = true,
      gridType = "polygon",
      showRadiusAxis = false,
      customTooltip,
      fillOpacity = 0.25,
      children,
      className,
      ...props
    },
    ref
  ) => {
    return (
      <motion.div
        ref={ref}
        className={cn("h-64 w-full sm:h-72", className)}
        {...props}
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsRadarChart data={data} outerRadius="70%">
            {showGridLines && (
              <PolarGrid
                gridType={gridType}
                className="stroke-zinc-200/80 dark:stroke-white/[0.08]"
              />
            )}
            <PolarAngleAxis
              dataKey={index}
              tick={{ fill: "currentColor", fontSize: 12 }}
              className="text-zinc-500 dark:text-zinc-400"
