            {showTooltip && (
              <Tooltip
                content={
                  customTooltip ? (
                    typeof customTooltip === "function" ? (
                      (customTooltip as any)
                    ) : (
                      React.cloneElement(
                        customTooltip as React.ReactElement,
                        {
                          valueFormatter,
                        } as any
                      )
                    )
                  ) : (
                    <ChartTooltip valueFormatter={valueFormatter} />
                  )
                }
