const defaultColors = [
  "var(--color-primary-500, #4F46E5)",
  "var(--color-cyan-500, #06B6D4)",
  "var(--color-success-500, #10B981)",
  "var(--color-warning-500, #F59E0B)",
  "var(--color-danger-500, #F43F5E)",
  "var(--color-secondary-500, #8B5CF6)",
];

const RadialChart = React.forwardRef<HTMLDivElement, RadialChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showLegend = true,
      showTooltip = true,
      innerRadius = "10%",
      outerRadius = "100%",
      startAngle = 90,
      endAngle = -270,
      customTooltip,
      children,
      className,
      ...props
    },
    ref
  ) => {
    // Inject fill color into data if not present (RadialBar uses the item's fill property natively)
    const processedData = data.map((item, idx) => ({
      ...item,
      fill: item.fill || colors[idx % colors.length],
    }));

    return (
      <motion.div
        ref={ref}
        className={cn("h-64 w-full sm:h-72", className)}
        {...props}
