            {categories.map((category) => (
              <RadialBar
                key={category}
                background={{ className: "fill-zinc-100 dark:fill-white/[0.04]" }}
                dataKey={category}
                cornerRadius={9999}
                isAnimationActive={false}
              />
            ))}
            {children}
          </RechartsRadialBarChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);
RadialChart.displayName = "RadialChart";

export { RadialChart };

