      baseTop = "6rem",
      offsetStep = "1.5rem",
      totalItems,
      className,
      classNames,
      ...props
    },
    ref
  ) => {
    const contextValue = React.useMemo(
      () => ({
        baseTop,
        offsetStep,
        totalItems,
      }),
      [baseTop, offsetStep, totalItems]
    );

    return (
      <StickyStackContext.Provider value={contextValue}>
        <div
