import { Tab, TabList, TabPanel, Tabs } from "../Tabs";
import { Text } from "../Text";
import { Check, Circle } from "lucide-react";
import type { BrandProfile, HeroContent, HeroSectionConfig } from "../CompositionSchema";
import { BrandScope, HeroSection } from "../HeroSection";
import { LandingFrame } from "../LandingShared";
import "./showcase.css";

export interface LandingBuilderVariant {
  id: string;
  label: string;
  description: string;
  config: HeroSectionConfig;
}

export interface LandingBuilderShowcaseProps {
  brand: BrandProfile;
  content: HeroContent;
  variants: LandingBuilderVariant[];
  initialVariant?: string;
  builderHref: string;
}

function LayoutThumbnail({
  config,
  content,
  mode,
}: {
  config: HeroSectionConfig;
  content: HeroContent;
  mode: BrandProfile["mode"];
}) {
  const image =
    "image" in config
      ? config.image
      : config.variant === "video"
        ? config.video.poster
        : config.variant === "slideshow"
          ? config.slides[0]
          : undefined;
  const src = mode === "dark" ? image?.darkSrc || image?.src : image?.src;
  const demo = config.variant === "interactive" ? config.tabs[0] : undefined;
  return (
    <div aria-hidden="true" className="hb-layout-art">
      <div className="hb-layout-sheet" data-layout={config.variant}>
        <div className="hb-layout-type">{content.title}</div>
        {src && <img src={src} alt="" loading="lazy" className="hb-layout-media" />}
        {demo && (
          <div className="hb-layout-demo">
            <strong>{demo.label}</strong>
            {demo.items.slice(0, 3).map((item, index) => (
              <span key={index}>{item}</span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export function LandingBuilderShowcase({
  brand,
  content,
  variants,
  initialVariant,
  builderHref,
}: LandingBuilderShowcaseProps) {
  const fallback = variants[0];
  const initial = variants.some((variant) => variant.id === initialVariant)
    ? initialVariant!
    : (fallback?.id ?? "");
  const [selected, setSelected] = React.useState(initial);
  const active = variants.find((variant) => variant.id === selected) ?? fallback;

  return (
    <LandingFrame id="builder">
      <header className="mx-auto mb-10 max-w-3xl text-center sm:mb-14">
        <Heading
          as="h2"
          size="inherit"
          className="hb-subheading text-[clamp(3.25rem,7vw,6.75rem)] leading-[0.94] font-medium tracking-[-0.055em]"
        >
          Change the layout. <span className="text-muted-foreground block">Keep the system.</span>
        </Heading>
        <Text className="text-muted-foreground mx-auto mt-6 max-w-[54ch] text-lg leading-relaxed text-balance sm:text-xl lg:text-2xl">
          Choose a hero composition and watch the same brand, content, spacing, and controls move
          with it.
        </Text>
      </header>
      {active ? (
        <Tabs selectedKey={active.id} onSelectionChange={setSelected} variant="light">
          <TabList aria-label="Hero layout" className="w-full">
            <BrandScope brand={brand}>
              <Grid cols={3} gap="sm" className="hb-layout-gallery">
                {variants.map((variant) => (
                  <Card
                    key={variant.id}
                    variant="bordered"
                    className="hb-layout-choice"
                    data-selected={variant.id === active.id}
                  >
                    <LayoutThumbnail config={variant.config} content={content} mode={brand.mode} />
                    <Tab tabKey={variant.id} className="hb-layout-tab">
                      <span>{variant.label}</span>
                      {variant.id === active.id ? (
                        <Check aria-hidden="true" size={16} />
                      ) : (
                        <Circle aria-hidden="true" size={14} />
                      )}
                    </Tab>
                  </Card>
                ))}
              </Grid>
            </BrandScope>
          </TabList>
          <Text role="status" aria-live="polite" className="sr-only">
            {active.label} preview selected.
          </Text>
          {variants.map((variant) => (
            <TabPanel key={variant.id} tabKey={variant.id} className="mt-5 min-w-0 sm:mt-8">
              <Text className="text-muted-foreground mx-auto mb-5 max-w-[58ch] text-center leading-relaxed">
                {variant.description}
              </Text>
              <MotionCrossfade transitionKey={variant.id}>
                <BrandScope
                  brand={brand}
                  data-builder-preview={variant.id}
                  className="hb-builder-showcase hb-radius border-border overflow-hidden border"
                >
                  <HeroSection content={content} config={variant.config} headingLevel="h3" />
                </BrandScope>
              </MotionCrossfade>
            </TabPanel>
          ))}
        </Tabs>
      ) : (
        <Text role="status">Add at least one hero variant to show the builder preview.</Text>
      )}
      <Button href={builderHref} className="hb-primary hb-radius mx-auto mt-8 flex w-fit">
        Open the full page builder
      </Button>
    </LandingFrame>
  );
}

.hb-layout-gallery .hb-layout-choice {
  flex-direction: row;
  align-items: center;
  padding: 0.375rem;
  border-radius: max(0.75rem, var(--hb-radius));
  border-color: var(--hb-border);
  background: var(--hb-bg);
  min-width: 0;
}
.hb-layout-choice[data-selected="true"] {
  border-color: var(--hb-accent);
  box-shadow: inset 0 0 0 1px var(--hb-accent);
}
.hb-layout-choice:focus-within {
  outline: 2px solid var(--hb-ink);
  outline-offset: 3px;
}
.hb-layout-choice .hb-layout-tab {
  position: static;
  flex: 1;
  min-width: 0;
  min-height: 44px;
  padding: 0.85rem 1rem;
  color: var(--hb-ink);
  background: transparent;
  box-shadow: none;
  transform: none;
}
.hb-layout-choice .hb-layout-tab::after {
  content: "";
  position: absolute;
  inset: 0;
}
.hb-layout-tab > span {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  text-align: start;
  white-space: normal;
}
.hb-layout-tab svg {
  flex: none;
  color: var(--hb-muted);
}
.hb-layout-tab[aria-selected="true"] svg {
  color: var(--hb-accent);
}
.hb-layout-art {
  container-type: inline-size;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32%;
  aspect-ratio: 1.6;
  overflow: hidden;
  border-radius: calc(max(0.75rem, var(--hb-radius)) - 0.375rem);
  background: var(--hb-surface);
}
.hb-layout-sheet {
  display: flex;
  align-items: center;
  gap: 5%;
  width: 88%;
  padding: 6%;
  border: 1px solid var(--hb-border);
  border-radius: 2cqw;
  background: var(--hb-bg);
  color: var(--hb-ink);
  box-shadow: 0 1.5cqw 4cqw color-mix(in srgb, var(--hb-ink) 9%, transparent);
}
.hb-layout-type {
  flex: 1;
  font-size: 5.2cqw;
  line-height: 1.05;
  letter-spacing: -0.045em;
  text-align: start;
  text-wrap: balance;
}
.hb-layout-media,
.hb-layout-demo {
  width: 50%;
  border-radius: 1cqw;
}
.hb-layout-sheet[data-layout="centered"] {
  flex-direction: column;
  gap: 2cqw;
}
.hb-layout-sheet[data-layout="centered"] .hb-layout-type {
  max-width: 16ch;
  text-align: center;
}
.hb-layout-sheet[data-layout="centered"] img {
  width: 82%;
}
.hb-layout-demo {
  padding: 2cqw;
  text-align: start;
  font-size: 2.8cqw;
  background: var(--hb-surface);
}
.hb-layout-demo span {
  display: block;
  margin-top: 1cqw;
  border-top: 1px solid var(--hb-border);
  padding-top: 1cqw;
}
@media (min-width: 48rem) {
  .hb-layout-gallery .hb-layout-choice {
    flex-direction: column;
    align-items: stretch;
  }
  .hb-layout-art {
    width: 100%;
    aspect-ratio: 1.18;
  }
}

.hb-builder-showcase .hb-section {
  --hb-section: clamp(2.5rem, 5vw, 4.5rem);
}

.hb-builder-showcase .hb-heading {
  font-size: clamp(2.25rem, 5vw, 4.25rem);
}

.hb-builder-showcase [role="tabpanel"] {
  scroll-margin-top: 1rem;
}

@media (max-width: 639px) {
  .hb-builder-showcase .hb-section > div {
    padding-inline: 1rem;
  }
}

