  const borderClass = cn(
    "absolute inset-0 border-[1.35px] border-zinc-900 dark:border-zinc-100 bg-white/35 dark:bg-zinc-950/35",
    dashed && "border-dashed border-zinc-500 dark:border-zinc-400"
