           ==================================================================== */
        <div ref={stackContainerRef} className="relative space-y-12 pt-2 pb-20 sm:space-y-16">
          {/* CARD STEP 01: PAGE BUILDER */}
          <StepStackCard
            index={0}
            numberLabel="01"
