export function LandingActionButton({
  action,
  secondary = false,
  fullWidth = false,
  size,
  className = "",
  onClick,
}: {
  action: LandingAction;
  secondary?: boolean;
  fullWidth?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
  onClick?: () => void;
}) {
  const { hrefFor } = useLandingNavigation();
  const href = hrefFor(action.href);

  if (secondary) {
    return (
      <Button
        href={href}
        variant="outline"
        size={size}
        onClick={onClick}
        className={cn("hb-secondary hb-radius", fullWidth && "w-full", className)}
