  chartIndex: string;
  chartCategories: string[];
  chartColors: string[];
  chartUnitPrefix?: string;
  chartUnitSuffix?: string;
  chartData: Record<string, string | number>[];
  kpis: { label: string; value: string; note: string }[];
  steps: ReasoningStep[];
  codeSnippet: string;
  summaryPoints: { title: string; detail: string }[];
}

