        Current: 62 + (warmPool ? 36 : 0),
        Baseline: 55,
      },
    ],
    [anycastTurbo, ebpfWaf, warmPool]
  );

  const edgeScore = React.useMemo(() => {
    const sum = radarData.reduce((acc, item) => acc + item.Current, 0);
    return Math.round(sum / radarData.length);
  }, [radarData]);

