  const activeSurfaceMode =
    controlledSurfaceMode !== undefined ? controlledSurfaceMode : uncontrolledSurface;
  const activeBlur = controlledBlur !== undefined ? controlledBlur : uncontrolledBlur;
  const activeIntensity =
