    setMusicPlaying(true);
  };

  const handlePrevTrack = () => {
    setIsAutoCycling(false);
    setTrackIndex((prev) => (prev - 1 + MUSIC_TRACKS.length) % MUSIC_TRACKS.length);
    setMusicSec(0);
    setMusicPlaying(true);
