                        .split(" ")[0]
                        .toLowerCase()
                        .replace(/[^a-z]/g, "") || "client"}{" "}
                      #success
                    </div>
                  </Card>
                </motion.div>
              ))}
            </motion.div>
          </div>
        </div>
      </Container>
    </Section>
  );
}

