              <span className="mt-1 font-serif text-[15px] tracking-widest whitespace-nowrap text-white drop-shadow-md">
                Close
              </span>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

