  {
    id: 3,
    name: "Product Updates",
    slug: "product-updates",
    count: 24,
    desc: "New features, releases, and changelogs.",
  },
  {
    id: 4,
    name: "Company",
    slug: "company",
    count: 5,
    desc: "Company news, culture, and announcements.",
