                    <motion.tr
                      key={cat.id}
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={{ opacity: 0, height: 0 }}
                      className="group hover:bg-muted/10 relative transition-colors"
