export const ModernAppTemplate = () => {
  const { scrollY } = useScroll();
  const [navVisible, setNavVisible] = useState(true);
  const [navCompact, setNavCompact] = useState(false);

  useMotionValueEvent(scrollY, "change", (current) => {
    const previous = scrollY.getPrevious() || 0;
    const diff = current - previous;
    if (current > 50) setNavCompact(true);
    else setNavCompact(false);
    if (current > 150 && diff > 5) setNavVisible(false);
    else if (diff < -5 || current <= 150) setNavVisible(true);
  });

  return (
    <div className="flex min-h-screen w-full flex-col bg-zinc-50 selection:bg-rose-500/30 dark:bg-zinc-950">
      <TemplateThemeToggle />
      <ModernAppNavbar navVisible={navVisible} navCompact={navCompact} />
      <ModernAppHero />
      <ModernAppLogoCloud />
      <ModernAppGrid />
      <ModernAppReflect />
      <ModernAppNetwork />
      <ModernAppRadar />
      <ModernAppMeetings />
      <ModernAppTestimonials />
      <ModernAppCta />
      <ModernAppFooter />
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { Moon, Sun } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

/** Provides the global dark/light toggle logic shared across the template */
export function useTemplateTheme() {
  const [theme, setTheme] = useState<"light" | "dark">("dark");

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove("light");
    root.classList.add("dark");
    setTheme("dark");
  }, []);

  const toggleTheme = () => {
    const root = window.document.documentElement;
    if (theme === "light") {
      root.classList.remove("light");
      root.classList.add("dark");
      setTheme("dark");
    } else {
      root.classList.remove("dark");
      root.classList.add("light");
      setTheme("light");
    }
  };

  return { theme, toggleTheme };
}

/** Inline theme toggle button — embed in the navbar */
export const ThemeToggleButton = ({
  theme,
  onToggle,
}: {
  theme: "light" | "dark";
  onToggle: () => void;
}) => (
  <motion.button
    onClick={onToggle}
    whileTap={{ scale: 0.9 }}
    className="flex h-9 w-9 items-center justify-center rounded-xl border border-zinc-200 bg-white text-zinc-600 shadow-sm transition-all hover:border-zinc-300 hover:bg-zinc-50 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-400 dark:hover:border-zinc-600 dark:hover:bg-zinc-700"
    aria-label="Toggle theme"
  >
    <AnimatePresence mode="wait" initial={false}>
      {theme === "light" ? (
        <motion.span
          key="moon"
          initial={{ rotate: -90, opacity: 0, scale: 0.5 }}
          animate={{ rotate: 0, opacity: 1, scale: 1 }}
          exit={{ rotate: 90, opacity: 0, scale: 0.5 }}
          transition={{ duration: 0.2 }}
        >
          <Moon size={16} />
        </motion.span>
      ) : (
        <motion.span
          key="sun"
          initial={{ rotate: 90, opacity: 0, scale: 0.5 }}
          animate={{ rotate: 0, opacity: 1, scale: 1 }}
          exit={{ rotate: -90, opacity: 0, scale: 0.5 }}
          transition={{ duration: 0.2 }}
        >
          <Sun size={16} />
        </motion.span>
      )}
    </AnimatePresence>
  </motion.button>
);

